#nullable enable

using System;
using UnityEngine;

namespace CrimsonDraft.Rendering
{
    /// <summary>
    /// Pool of pre-baked zombie looks. Each variant is a Body + Details material pair generated by
    /// the Zombie Variant Generator editor window. <see cref="BaseBody"/> / <see cref="BaseDetails"/>
    /// are the materials baked into the zombie prefabs, which <see cref="ZombieVariantRandomizer"/>
    /// swaps for a random variant at runtime.
    /// </summary>
    [CreateAssetMenu(menuName = "CrimsonDraft/Zombie Variant Set")]
    public sealed class ZombieVariantSet : ScriptableObject
    {
        [Serializable]
        public struct Variant
        {
            public Material Body;
            public Material Details;
        }

        public Material? BaseBody;
        public Material? BaseDetails;
        public Variant[] Variants = Array.Empty<Variant>();
    }
}
